export const WORKFLOW_EAS_BUILD_TEMPLATE = '# managed-by: k1w1\n# workflow-version: 405\nname: EAS Build\n\non:\n  workflow_dispatch:\n    inputs:\n      ref:\n        description: "Branch/Tag/SHA to build"\n        required: true\n      profile:\n        description: "EAS build profile (development|preview|production)"\n        required: false\n        default: "preview"\n      job_id:\n        description: "Supabase build job id (optional)"\n        required: false\n        default: ""\n      platform:\n        description: "Platform"\n        required: false\n        type: choice\n        options: [android]\n        default: android\n      autofix:\n        description: "Allow workflow to write back fixes (lockfile/dev-client) to the branch"\n        required: false\n        type: boolean\n        default: false\n      strict_lockfile:\n        description: "Lockfile policy override (auto|true|false)"\n        required: false\n        type: choice\n        options: [auto, "true", "false"]\n        default: auto\n\n  workflow_call:\n    inputs:\n      ref:\n        description: "Branch/Tag/SHA to build"\n        required: true\n        type: string\n      profile:\n        description: "EAS build profile (development|preview|production)"\n        required: false\n        type: string\n        default: "preview"\n      job_id:\n        description: "Supabase build job id (optional)"\n        required: false\n        type: string\n        default: ""\n      platform:\n        description: "Platform"\n        required: false\n        type: string\n        default: "android"\n      autofix:\n        description: "Allow workflow to write back fixes (lockfile/dev-client) to the branch"\n        required: false\n        type: boolean\n        default: false\n      strict_lockfile:\n        description: "Lockfile policy override (auto|true|false)"\n        required: false\n        type: string\n        default: "auto"\n    secrets:\n      EXPO_TOKEN:\n        required: true\n      SUPABASE_URL:\n        required: false\n      SUPABASE_SERVICE_ROLE_KEY:\n        required: false\n      SUPABASE_APK_BUCKET:\n        required: false\n      K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY:\n        required: false\n\npermissions:\n  contents: read\n\nconcurrency:\n  group: eas-build-${{ inputs.ref }}-${{ inputs.profile }}\n  cancel-in-progress: false\n\njobs:\n  autofix:\n    name: Auto-fix repo (optional writeback)\n    if: ${{ inputs.autofix == true }}\n    runs-on: ubuntu-latest\n    timeout-minutes: 30\n    permissions:\n      contents: write\n\n    env:\n      EXPO_TOKEN: ${{ secrets.EXPO_TOKEN }}\n      EAS_CLI_VERSION: "16.32.0"\n      WORKFLOW_VERSION: "405"\n\n    steps:\n      - name: Checkout\n        uses: actions/checkout@34e114876b0b11c390a56381ad16ebd13914f8d5 # v4\n        with:\n          ref: ${{ inputs.ref }}\n          fetch-depth: 0\n          persist-credentials: false\n\n      - name: "🧹 Preflight: clean incomplete native dirs"\n        shell: bash\n        run: |\n          set -euo pipefail\n          # Managed workflow guard:\n          # If android/ or ios/ exists but is incomplete, EAS can choke.\n          # Only delete when we detect it\'s clearly incomplete.\n          if [ -d android ]; then\n            if [ ! -f android/build.gradle ] || [ ! -f android/app/build.gradle ]; then\n              echo "::warning::Found incomplete android/ directory (missing build.gradle). Removing android/ to allow EAS to regenerate native project."\n              rm -rf android\n            fi\n          fi\n\n          if [ -d ios ]; then\n            if [ ! -f ios/Podfile ]; then\n              echo "::warning::Found incomplete ios/ directory (missing Podfile). Removing ios/ to allow EAS to regenerate native project."\n              rm -rf ios\n            fi\n          fi\n\n      - name: Detect package manager / lockfile (for cache + install strategy)\n        id: lock\n        shell: bash\n        run: |\n          set -euo pipefail\n          if [ -f package-lock.json ]; then\n            {\n              echo "has_lockfile=true"\n              echo "lockfile_path=package-lock.json"\n              echo "package_manager=npm"\n            } >> "$GITHUB_OUTPUT"\n          elif [ -f npm-shrinkwrap.json ]; then\n            {\n              echo "has_lockfile=true"\n              echo "lockfile_path=npm-shrinkwrap.json"\n              echo "package_manager=npm"\n            } >> "$GITHUB_OUTPUT"\n          elif [ -f yarn.lock ]; then\n            {\n              echo "has_lockfile=true"\n              echo "lockfile_path=yarn.lock"\n              echo "package_manager=yarn"\n            } >> "$GITHUB_OUTPUT"\n          elif [ -f pnpm-lock.yaml ]; then\n            {\n              echo "has_lockfile=true"\n              echo "lockfile_path=pnpm-lock.yaml"\n              echo "package_manager=pnpm"\n            } >> "$GITHUB_OUTPUT"\n          else\n            {\n              echo "has_lockfile=false"\n              echo "lockfile_path="\n              echo "package_manager=npm"\n            } >> "$GITHUB_OUTPUT"\n          fi\n\n      - name: Determine strict lockfile policy\n        id: strict_lock\n        shell: bash\n        run: |\n          set -euo pipefail\n          PROFILE="${{ inputs.profile }}"\n          OVERRIDE="${{ inputs.strict_lockfile }}"\n          case "$OVERRIDE" in\n            true)\n              echo "strict=true" >> "$GITHUB_OUTPUT"\n              ;;\n            false)\n              if [ "$PROFILE" != "development" ]; then\n                echo "::error::strict_lockfile=false is only allowed for development profile. Preview/production remain fail-closed."\n                exit 1\n              fi\n              echo "strict=false" >> "$GITHUB_OUTPUT"\n              ;;\n            ""|auto)\n              case "$PROFILE" in\n                preview|production)\n                  echo "strict=true" >> "$GITHUB_OUTPUT"\n                  ;;\n                development)\n                  echo "strict=false" >> "$GITHUB_OUTPUT"\n                  ;;\n                *)\n                  echo "::error::Unknown profile \'$PROFILE\' while computing strict lockfile policy"\n                  exit 1\n                  ;;\n              esac\n              ;;\n            *)\n              echo "::error::Invalid strict_lockfile override \'$OVERRIDE\' (allowed: auto|true|false)"\n              exit 1\n              ;;\n          esac\n\n      - name: Setup Node (npm cache)\n        if: steps.lock.outputs.has_lockfile == \'true\' && steps.lock.outputs.package_manager == \'npm\'\n        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4\n        with:\n          node-version: 20\n          cache: npm\n          cache-dependency-path: ${{ steps.lock.outputs.lockfile_path }}\n\n      - name: Setup Node (yarn cache)\n        if: steps.lock.outputs.has_lockfile == \'true\' && steps.lock.outputs.package_manager == \'yarn\'\n        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4\n        with:\n          node-version: 20\n          cache: yarn\n          cache-dependency-path: ${{ steps.lock.outputs.lockfile_path }}\n\n      - name: Setup Node (pnpm cache)\n        if: steps.lock.outputs.has_lockfile == \'true\' && steps.lock.outputs.package_manager == \'pnpm\'\n        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4\n        with:\n          node-version: 20\n          cache: pnpm\n          cache-dependency-path: ${{ steps.lock.outputs.lockfile_path }}\n\n      - name: Setup Node (no cache - lockfile missing)\n        if: steps.lock.outputs.has_lockfile != \'true\'\n        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4\n        with:\n          node-version: 20\n\n      - name: Install dependencies (policy-aware)\n        id: install_deps\n        shell: bash\n        env:\n          STRICT_LOCKFILE: ${{ steps.strict_lock.outputs.strict }}\n        run: |\n          set -euo pipefail\n          PROFILE="${{ inputs.profile }}"\n          PM="${{ steps.lock.outputs.package_manager }}"\n          LOCKFILE="${{ steps.lock.outputs.lockfile_path }}"\n          if [ "${{ steps.lock.outputs.has_lockfile }}" = "true" ]; then\n            case "$PM" in\n              npm)\n                echo "Using npm ci (lockfile: ${LOCKFILE})"\n                echo "mode=lockfile-${PM}" >> "$GITHUB_OUTPUT"\n                npm ci --no-audit --no-fund\n                ;;\n              yarn)\n                echo "Using yarn install --immutable (lockfile: ${LOCKFILE})"\n                echo "mode=lockfile-${PM}" >> "$GITHUB_OUTPUT"\n                corepack enable || true\n                yarn install --immutable\n                ;;\n              pnpm)\n                echo "Using pnpm install --frozen-lockfile (lockfile: ${LOCKFILE})"\n                echo "mode=lockfile-${PM}" >> "$GITHUB_OUTPUT"\n                corepack enable || true\n                pnpm install --frozen-lockfile\n                ;;\n              *)\n                echo "::error::Unknown package manager \'$PM\'"\n                exit 1\n                ;;\n            esac\n          elif [ "${STRICT_LOCKFILE}" = "true" ]; then\n            echo "::error::Strict lockfile policy enabled for profile \'${PROFILE}\', but no lockfile was found. Commit package-lock.json, npm-shrinkwrap.json, yarn.lock or pnpm-lock.yaml before running preview/production builds."\n            exit 1\n          else\n            echo "::warning::No lockfile found in repo. Development profile allows fallback to npm install (non-reproducible)."\n            echo "mode=fallback-npm-install" >> "$GITHUB_OUTPUT"\n            npm install --no-audit --no-fund\n          fi\n\n      - name: Install EAS CLI (pinned)\n        shell: bash\n        run: |\n          set -euo pipefail\n          npm i -g "eas-cli@${EAS_CLI_VERSION}"\n          eas --version | tee ci-logs/eas-version.log\n\n      - name: Verify EAS auth\n        shell: bash\n        run: |\n          set -euo pipefail\n          if [ -z "${EXPO_TOKEN:-}" ]; then\n            echo "::error::Missing GitHub Secret EXPO_TOKEN"\n            exit 1\n          fi\n          eas whoami | tee ci-logs/eas-whoami.log\n\n      - name: Auto-fix repo (lockfile + dev client) [optional writeback]\n        shell: bash\n        env:\n          TARGET_BRANCH: ${{ inputs.ref }}\n          PROFILE: ${{ inputs.profile }}\n          PACKAGE_MANAGER: ${{ steps.lock.outputs.package_manager }}\n          HAS_LOCKFILE: ${{ steps.lock.outputs.has_lockfile }}\n          LOCKFILE_PATH: ${{ steps.lock.outputs.lockfile_path }}\n          GITHUB_TOKEN: ${{ github.token }}\n        run: |\n          set -euo pipefail\n\n          PM="${PACKAGE_MANAGER:-npm}"\n          echo "🧯 Auto-fix: lockfile + expo-dev-client (development only)."\n          if [ "$PM" != "npm" ]; then\n            echo "::notice::Auto-fix writeback currently supports npm-managed repos only. Detected package manager \'$PM\'; skipping writeback path."\n            exit 0\n          fi\n\n          npm config set package-lock true\n\n          if [ "${PROFILE}" = "development" ]; then\n            echo "📦 Ensuring expo-dev-client for development builds..."\n            npx --yes expo install expo-dev-client --fix || npx --yes expo install expo-dev-client\n          fi\n\n          if [ "${HAS_LOCKFILE}" != "true" ] || [ ! -f "${LOCKFILE_PATH:-package-lock.json}" ]; then\n            echo "::warning::No npm lockfile found. Generating package-lock.json (best effort)."\n            npm install --package-lock-only --no-audit --no-fund\n          fi\n\n          # Determine if package.json / package-lock.json / .npmrc changed (modified or untracked)\n          if ! git status --porcelain -- package.json package-lock.json .npmrc | grep -q .; then\n            echo "ℹ️ No CI auto-fix changes to write back."\n            exit 0\n          fi\n\n          BR="${TARGET_BRANCH:-}"\n          if [ -z "$BR" ]; then\n            echo "::warning::No TARGET_BRANCH provided; skipping writeback."\n            exit 0\n          fi\n\n          if echo "$BR" | grep -qE \'^[0-9a-fA-F]{7,40}$\'; then\n            echo "::warning::Ref looks like a SHA ($BR). Skipping writeback."\n            exit 0\n          fi\n          if echo "$BR" | grep -qE \'[: ]\'; then\n            echo "::warning::Unsafe ref ($BR). Skipping writeback."\n            exit 0\n          fi\n          if ! echo "$BR" | grep -qE "${ALLOWED_REF_REGEX}"; then\n            echo "::warning::Writeback disabled for branch \'$BR\' (regex: ${ALLOWED_REF_REGEX})."\n            exit 0\n          fi\n\n          git remote set-url origin "https://x-access-token:${GITHUB_TOKEN}@github.com/${GITHUB_REPOSITORY}.git"\n          if ! git ls-remote --exit-code --heads origin "$BR" >/dev/null 2>&1; then\n            echo "::warning::Ref \'$BR\' is not a remote branch. Skipping writeback."\n            exit 0\n          fi\n\n          echo "✅ Auto-fix changes detected -> committing back to \'$BR\'."\n          git config user.email "actions@users.noreply.github.com"\n          git config user.name "github-actions[bot]"\n          git add package.json package-lock.json .npmrc 2>/dev/null || true\n          git commit -m "chore(ci): auto-fix lockfile/dev-client [skip ci]" || true\n\n          echo "🚀 Pushing to origin $BR (best effort)..."\n          git push origin "HEAD:$BR" || echo "::warning::Could not push auto-fix commit (branch may be protected)."\n\n  build:\n    needs: [autofix]\n    if: ${{ always() && (needs.autofix.result == \'success\' || needs.autofix.result == \'skipped\') }}\n    permissions:\n      contents: read\n\n    runs-on: ubuntu-latest\n    timeout-minutes: 60\n\n    env:\n      EXPO_TOKEN: ${{ secrets.EXPO_TOKEN }}\n      EAS_CLI_VERSION: "16.32.0"\n\n      SUPABASE_URL: ${{ secrets.SUPABASE_URL }}\n      SUPABASE_SERVICE_ROLE_KEY: ${{ secrets.SUPABASE_SERVICE_ROLE_KEY }}\n      K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY: ${{ secrets.K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY }}\n      JOB_ID: ${{ inputs.job_id }}\n\n    steps:\n      - name: Validate inputs\n        shell: bash\n        run: |\n          set -euo pipefail\n\n          case "${{ inputs.profile }}" in\n            development|preview|production) ;;\n            *)\n              echo "::error::Invalid profile: \'${{ inputs.profile }}\' (allowed: development|preview|production)"\n              exit 1\n              ;;\n          esac\n\n          if [ -z "${EXPO_TOKEN:-}" ]; then\n            echo "::error::Missing GitHub Secret EXPO_TOKEN"\n            exit 1\n          fi\n\n          if [ "${{ inputs.profile }}" = "production" ]; then\n            if [ -z "${SUPABASE_URL:-}" ] || [ -z "${SUPABASE_SERVICE_ROLE_KEY:-}" ] || [ -z "${K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY:-}" ]; then\n              echo "::error::Production build requires SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, and K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY."\n              exit 1\n            fi\n          fi\n\n          echo "ARTIFACT_EXT=apk" >> "$GITHUB_ENV"\n\n          if [ -z "${JOB_ID:-}" ]; then\n            echo "has_job_id=false" >> "$GITHUB_ENV"\n          else\n            if [ -z "${SUPABASE_URL:-}" ] || [ -z "${SUPABASE_SERVICE_ROLE_KEY:-}" ]; then\n              echo "::warning::JOB_ID provided, but SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY missing -> status updates will be skipped."\n              echo "has_job_id=false" >> "$GITHUB_ENV"\n            else\n              echo "has_job_id=true" >> "$GITHUB_ENV"\n            fi\n          fi\n\n      - name: Checkout\n        uses: actions/checkout@34e114876b0b11c390a56381ad16ebd13914f8d5 # v4\n        with:\n          ref: ${{ inputs.ref }}\n          fetch-depth: 0\n          persist-credentials: false\n\n      - name: Prepare build diagnostics dir\n        shell: bash\n        run: |\n          set -euo pipefail\n          mkdir -p ci-logs\n\n      - name: "🧹 Preflight: clean incomplete native dirs"\n        shell: bash\n        run: |\n          set -euo pipefail\n          # Managed workflow guard:\n          # If android/ or ios/ exists but is incomplete, EAS/Expo can choke.\n          # Only delete when it\'s clearly incomplete (missing the canonical files).\n\n          if [ -d android ]; then\n            if [ ! -f android/build.gradle ] || [ ! -f android/app/build.gradle ]; then\n              echo "::warning::Found incomplete android/ directory (missing build.gradle). Removing to allow managed EAS build to regenerate native project."\n              rm -rf android\n            fi\n          fi\n\n          if [ -d ios ]; then\n            if [ ! -f ios/Podfile ]; then\n              echo "::warning::Found incomplete ios/ directory (missing Podfile). Removing to allow managed EAS build to regenerate native project."\n              rm -rf ios\n            fi\n          fi\n\n      - name: Detect package manager / lockfile (for cache + install strategy)\n        id: lock\n        shell: bash\n        run: |\n          set -euo pipefail\n          if [ -f package-lock.json ]; then\n            {\n              echo "has_lockfile=true"\n              echo "lockfile_path=package-lock.json"\n              echo "package_manager=npm"\n            } >> "$GITHUB_OUTPUT"\n          elif [ -f npm-shrinkwrap.json ]; then\n            {\n              echo "has_lockfile=true"\n              echo "lockfile_path=npm-shrinkwrap.json"\n              echo "package_manager=npm"\n            } >> "$GITHUB_OUTPUT"\n          elif [ -f yarn.lock ]; then\n            {\n              echo "has_lockfile=true"\n              echo "lockfile_path=yarn.lock"\n              echo "package_manager=yarn"\n            } >> "$GITHUB_OUTPUT"\n          elif [ -f pnpm-lock.yaml ]; then\n            {\n              echo "has_lockfile=true"\n              echo "lockfile_path=pnpm-lock.yaml"\n              echo "package_manager=pnpm"\n            } >> "$GITHUB_OUTPUT"\n          else\n            {\n              echo "has_lockfile=false"\n              echo "lockfile_path="\n              echo "package_manager=npm"\n            } >> "$GITHUB_OUTPUT"\n          fi\n          echo "Repo root: $(pwd)"\n          echo "Files:"; ls -lah\n\n      - name: Determine strict lockfile policy\n        id: strict_lock\n        shell: bash\n        run: |\n          set -euo pipefail\n          PROFILE="${{ inputs.profile }}"\n          OVERRIDE="${{ inputs.strict_lockfile }}"\n          case "$OVERRIDE" in\n            true)\n              echo "strict=true" >> "$GITHUB_OUTPUT"\n              ;;\n            false)\n              if [ "$PROFILE" != "development" ]; then\n                echo "::error::strict_lockfile=false is only allowed for development profile. Preview/production remain fail-closed."\n                exit 1\n              fi\n              echo "strict=false" >> "$GITHUB_OUTPUT"\n              ;;\n            ""|auto)\n              case "$PROFILE" in\n                preview|production)\n                  echo "strict=true" >> "$GITHUB_OUTPUT"\n                  ;;\n                development)\n                  echo "strict=false" >> "$GITHUB_OUTPUT"\n                  ;;\n                *)\n                  echo "::error::Unknown profile \'$PROFILE\' while computing strict lockfile policy"\n                  exit 1\n                  ;;\n              esac\n              ;;\n            *)\n              echo "::error::Invalid strict_lockfile override \'$OVERRIDE\' (allowed: auto|true|false)"\n              exit 1\n              ;;\n          esac\n\n      - name: Setup Node (npm cache)\n        if: steps.lock.outputs.has_lockfile == \'true\' && steps.lock.outputs.package_manager == \'npm\'\n        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4\n        with:\n          node-version: 20\n          cache: npm\n          cache-dependency-path: ${{ steps.lock.outputs.lockfile_path }}\n\n      - name: Setup Node (yarn cache)\n        if: steps.lock.outputs.has_lockfile == \'true\' && steps.lock.outputs.package_manager == \'yarn\'\n        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4\n        with:\n          node-version: 20\n          cache: yarn\n          cache-dependency-path: ${{ steps.lock.outputs.lockfile_path }}\n\n      - name: Setup Node (pnpm cache)\n        if: steps.lock.outputs.has_lockfile == \'true\' && steps.lock.outputs.package_manager == \'pnpm\'\n        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4\n        with:\n          node-version: 20\n          cache: pnpm\n          cache-dependency-path: ${{ steps.lock.outputs.lockfile_path }}\n\n      - name: Setup Node (no cache - lockfile missing)\n        if: steps.lock.outputs.has_lockfile != \'true\'\n        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4\n        with:\n          node-version: 20\n\n      - name: Install dependencies (policy-aware)\n        id: install_deps\n        shell: bash\n        env:\n          STRICT_LOCKFILE: ${{ steps.strict_lock.outputs.strict }}\n        run: |\n          set -euo pipefail\n          PROFILE="${{ inputs.profile }}"\n          PM="${{ steps.lock.outputs.package_manager }}"\n          LOCKFILE="${{ steps.lock.outputs.lockfile_path }}"\n          if [ "${{ steps.lock.outputs.has_lockfile }}" = "true" ]; then\n            case "$PM" in\n              npm)\n                echo "Using npm ci (lockfile: ${LOCKFILE})"\n                echo "mode=lockfile-${PM}" >> "$GITHUB_OUTPUT"\n                npm ci --no-audit --no-fund\n                ;;\n              yarn)\n                echo "Using yarn install --immutable (lockfile: ${LOCKFILE})"\n                echo "mode=lockfile-${PM}" >> "$GITHUB_OUTPUT"\n                corepack enable || true\n                yarn install --immutable\n                ;;\n              pnpm)\n                echo "Using pnpm install --frozen-lockfile (lockfile: ${LOCKFILE})"\n                echo "mode=lockfile-${PM}" >> "$GITHUB_OUTPUT"\n                corepack enable || true\n                pnpm install --frozen-lockfile\n                ;;\n              *)\n                echo "::error::Unknown package manager \'$PM\'"\n                exit 1\n                ;;\n            esac\n          elif [ "${STRICT_LOCKFILE}" = "true" ]; then\n            echo "::error::Strict lockfile policy enabled for profile \'${PROFILE}\', but no lockfile was found. Commit package-lock.json, npm-shrinkwrap.json, yarn.lock or pnpm-lock.yaml before running preview/production builds."\n            exit 1\n          else\n            echo "::warning::No lockfile found in repo. Development profile allows fallback to npm install (non-reproducible)."\n            echo "mode=fallback-npm-install" >> "$GITHUB_OUTPUT"\n            npm install --no-audit --no-fund\n          fi\n\n      - name: Install EAS CLI (pinned)\n        shell: bash\n        run: |\n          set -euo pipefail\n          npm i -g "eas-cli@${EAS_CLI_VERSION}"\n          eas --version | tee ci-logs/eas-version.log\n\n      - name: Verify EAS auth\n        shell: bash\n        run: |\n          set -euo pipefail\n          eas whoami | tee ci-logs/eas-whoami.log\n\n      - name: Production credential preflight\n        if: ${{ inputs.profile == \'production\' }}\n        shell: bash\n        env:\n          K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY: ${{ secrets.K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY }}\n          WORKFLOW_REF: ${{ inputs.ref }}\n        run: |\n          set -euo pipefail\n          echo "::add-mask::${SUPABASE_SERVICE_ROLE_KEY}"\n          if [ -z "${K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY:-}" ]; then\n            echo "::error::Missing K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY for production keystore export."\n            exit 1\n          fi\n          if [ -n "${K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY:-}" ]; then\n            echo "::add-mask::${K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY}"\n          fi\n          node -e \'\n            const fs = require("fs");\n            const payload = {\n              repo: process.env.GITHUB_REPOSITORY,\n              mode: "production",\n              run_id: process.env.GITHUB_RUN_ID,\n              ref: process.env.WORKFLOW_REF || "",\n              profile: "production"\n            };\n            fs.mkdirSync("ci-logs", { recursive: true });\n            fs.writeFileSync("ci-logs/keystore-request.json", JSON.stringify(payload, null, 2));\n          \'\n\n      - name: Fetch Android keystore (production only)\n        if: ${{ inputs.profile == \'production\' }}\n        shell: bash\n        env:\n          K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY: ${{ secrets.K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY }}\n        run: |\n          set -euo pipefail\n          mkdir -p ci-logs\n\n          CURL_ARGS=(\n            --silent\n            --show-error\n            --retry 3\n            --retry-all-errors\n            --connect-timeout 10\n            --max-time 60\n            -o ci-logs/keystore-response.raw.json\n            -w "%{http_code}"\n            -X POST "${SUPABASE_URL%/}/functions/v1/android-keystore-export"\n            -H "Content-Type: application/json"\n            -H "apikey: ${SUPABASE_SERVICE_ROLE_KEY}"\n            -H "Authorization: Bearer ${SUPABASE_SERVICE_ROLE_KEY}"\n            -d @ci-logs/keystore-request.json\n          )\n\n          if [ -n "${K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY:-}" ]; then\n            CURL_ARGS+=(-H "x-k1w1-admin-key: ${K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY}")\n          fi\n\n          HTTP_CODE="$(\n            curl "${CURL_ARGS[@]}"\n          )"\n\n          echo "$HTTP_CODE" > ci-logs/keystore-response.http_code\n\n          if [ "$HTTP_CODE" != "200" ]; then\n            node -e \'\n              const fs = require("fs");\n              const raw = fs.existsSync("ci-logs/keystore-response.raw.json")\n                ? fs.readFileSync("ci-logs/keystore-response.raw.json", "utf8")\n                : "";\n              const sanitized = raw\n                .replace(/[A-Za-z0-9+/=]{24,}/g, "[redacted]")\n                .replace(/Bearer\\s+[A-Za-z0-9._-]+/g, "Bearer [redacted]");\n              fs.writeFileSync("ci-logs/keystore-response.sanitized.txt", sanitized);\n            \'\n            echo "::error::Keystore export failed with HTTP ${HTTP_CODE}. See sanitized diagnostics artifact."\n            exit 1\n          fi\n      - name: Validate keystore export structure\n        if: ${{ inputs.profile == \'production\' }}\n        shell: bash\n        run: |\n          set -euo pipefail\n          node -e \'\n            const fs = require("fs");\n            const p = "ci-logs/keystore-response.raw.json";\n            const raw = fs.readFileSync(p, "utf8");\n            let data;\n            try {\n              data = JSON.parse(raw);\n            } catch (err) {\n              fs.writeFileSync("ci-logs/keystore-response.sanitized.txt", raw.slice(0, 4000));\n              console.error("Keystore export is not valid JSON");\n              process.exit(1);\n            }\n            const summary = {\n              topLevelKeys: Object.keys(data || {}).slice(0, 20),\n              ok: data?.ok === true,\n              hasKeystoreBase64: typeof data?.keystoreBase64 === "string" && data.keystoreBase64.length > 0,\n              hasKeystorePassword: typeof data?.keystorePassword === "string" && data.keystorePassword.length > 0,\n              hasAlias: typeof data?.alias === "string" && data.alias.length > 0,\n              hasKeyPassword: typeof data?.keyPassword === "string" && data.keyPassword.length > 0\n            };\n            fs.writeFileSync("ci-logs/keystore-response.summary.json", JSON.stringify(summary, null, 2));\n            if (!summary.ok || !summary.hasKeystoreBase64 || !summary.hasKeystorePassword || !summary.hasAlias || !summary.hasKeyPassword) {\n              fs.writeFileSync("ci-logs/keystore-response.sanitized.txt", JSON.stringify(summary, null, 2));\n              console.error("Keystore export payload missing required fields");\n              process.exit(1);\n            }\n          \'\n\n      - name: Write Android signing files\n        if: ${{ inputs.profile == \'production\' }}\n        shell: bash\n        run: |\n          set -euo pipefail\n          node scripts/ci/writeAndroidSigningFilesFromExport.js < ci-logs/keystore-response.raw.json\n\n      - name: Update Build Status - Building\n        if: env.has_job_id == \'true\'\n        shell: bash\n        run: |\n          set -euo pipefail\n          TS="$(date -u +"%Y-%m-%dT%H:%M:%SZ")"\n          RUN_ID="${{ github.run_id }}"\n          PROFILE="${{ inputs.profile }}"\n          SOURCE_COMMIT_SHA="$(git rev-parse HEAD)"\n          JSON="$(node -e \'console.log(JSON.stringify({status:"building",build_profile:process.argv[1],github_run_id:process.argv[2],started_at:process.argv[3],source_commit_sha:process.argv[4]}))\' "${PROFILE}" "${RUN_ID}" "${TS}" "${SOURCE_COMMIT_SHA}")"\n          curl --fail-with-body --silent --show-error             -X PATCH "${SUPABASE_URL%/}/rest/v1/build_jobs?id=eq.${JOB_ID}"             -H "apikey: ${SUPABASE_SERVICE_ROLE_KEY}"             -H "Authorization: Bearer ${SUPABASE_SERVICE_ROLE_KEY}"             -H "Content-Type: application/json"             -H "Prefer: return=minimal"             -d "${JSON}"             || echo "::warning::Failed to update Supabase status (building)"\n\n      - name: Run EAS Build (WAIT)\n        id: eas\n        shell: bash\n        run: |\n          set -euo pipefail\n          PROFILE="${{ inputs.profile }}"\n          PLATFORM="${{ inputs.platform }}"\n          echo "🚀 Starting EAS build (platform=${PLATFORM}, profile=${PROFILE}) with --wait..."\n          BUILD_OUTPUT="$(eas build --platform "${PLATFORM}" --profile "${PROFILE}" --non-interactive --wait 2>&1)" || {\n            CODE=$?\n            echo "${BUILD_OUTPUT}" | tee ci-logs/eas-build.log\n            if echo "${BUILD_OUTPUT}" | grep -q "Generating a new Keystore is not supported in --non-interactive mode"; then\n              echo "::error::Android signing keystore is missing on EAS. Fix: run \'eas credentials -p android\' once locally (interactive) to generate/upload a keystore, or configure Android credentials in the Expo dashboard, then rerun the workflow."\n            fi\n            if echo "${BUILD_OUTPUT}" | grep -qiE "build\\.gradle|android/app"; then\n              echo "::warning::Build mentions Android native files. If this is a managed Expo project, ensure no partial \'android/\' folder is committed (or let the workflow preflight delete it)."\n            fi\n            echo "::error::EAS build failed (exit ${CODE})"\n            exit "${CODE}"\n          }\n          echo "${BUILD_OUTPUT}" | tee ci-logs/eas-build.log\n          UUID_RE=\'[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\'\n          BUILD_ID="$(echo "${BUILD_OUTPUT}" | grep -oE "${UUID_RE}" | head -n1 || true)"\n          if [ -z "${BUILD_ID}" ]; then BUILD_ID="unknown"; fi\n          echo "build_id=${BUILD_ID}" >> "${GITHUB_OUTPUT}"\n          BUILD_URL="$(echo "${BUILD_OUTPUT}" | grep -oE "https://expo.dev[^[:space:]]*/builds/${UUID_RE}" | head -n1 || true)"\n          echo "build_url=${BUILD_URL}" >> "${GITHUB_OUTPUT}"\n\n      - name: Download Android Artifact\n        if: steps.eas.outputs.build_id != \'unknown\' && steps.eas.outputs.build_id != \'\'\n        continue-on-error: true\n        shell: bash\n        run: |\n          set -euo pipefail\n          mkdir -p build\n          OUT="build/k1w1-${{ inputs.profile }}.${ARTIFACT_EXT}"\n          eas build:download             --id "${{ steps.eas.outputs.build_id }}"             --output "${OUT}" || {\n              echo "::warning::Failed to download artifact"\n              exit 0\n            }\n          ls -lah build || true\n\n      - name: Upload build diagnostics\n        if: always()\n        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02 # v4\n        with:\n          name: eas-build-diagnostics-${{ github.run_number }}\n          path: |\n            ci-logs/eas-version.log\n            ci-logs/eas-whoami.log\n            ci-logs/eas-build.log\n            ci-logs/keystore-response.http_code\n            ci-logs/keystore-response.summary.json\n            ci-logs/keystore-response.sanitized.txt\n          retention-days: 3\n          if-no-files-found: ignore\n\n      - name: Cleanup signing files\n        if: always()\n        shell: bash\n        run: |\n          set +e\n          rm -f credentials.json android-upload-keystore.p12\n          rm -f android/keystore.jks android/app/keystore.jks android/keystore.properties\n          rm -f ci-logs/keystore-response.raw.json\n          true\n\n      - name: Upload Artifact\n        if: always()\n        continue-on-error: true\n        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02 # v4\n        with:\n          name: eas-${{ inputs.platform }}-${{ inputs.profile }}-${{ github.run_number }}\n          path: build/*\n          retention-days: 30\n          if-no-files-found: warn\n\n      - name: Summary\n        if: always()\n        shell: bash\n        run: |\n          cat >> "$GITHUB_STEP_SUMMARY" << EOF\n          ## EAS Build Summary\n\n          - Workflow version: ${WORKFLOW_VERSION}\n          - Repo: ${{ github.repository }}\n          - Input ref: ${{ inputs.ref }}\n          - Input profile: ${{ inputs.profile }}\n          - Platform: ${{ inputs.platform }}\n          - Checked out: $(git rev-parse HEAD)\n          - Package manager: ${{ steps.lock.outputs.package_manager }}\n          - Lockfile present: ${{ steps.lock.outputs.has_lockfile }}\n          - Lockfile path: ${{ steps.lock.outputs.lockfile_path }}\n          - Strict lockfile policy: ${{ steps.strict_lock.outputs.strict }}\n          - Dependency install mode: ${{ steps.install_deps.outputs.mode }}\n          - EAS CLI: $(eas --version 2>/dev/null || echo "unknown")\n          - Build ID: ${{ steps.eas.outputs.build_id }}\n          - Build URL: ${{ steps.eas.outputs.build_url }}\n          - Diagnostics artifact: eas-build-diagnostics-${{ github.run_number }}\n\n          Artifacts: https://github.com/${{ github.repository }}/actions/runs/${{ github.run_id }}\n          EOF\n\n      - name: Update Build Status - Success\n        if: success() && env.has_job_id == \'true\'\n        shell: bash\n        run: |\n          set -euo pipefail\n          TS="$(date -u +"%Y-%m-%dT%H:%M:%SZ")"\n          RUN_ID="${{ github.run_id }}"\n          BUILD_ID="${{ steps.eas.outputs.build_id }}"\n          BUILD_URL="${{ steps.eas.outputs.build_url }}"\n          SOURCE_COMMIT_SHA="$(git rev-parse HEAD)"\n          JSON="$(node -e \'console.log(JSON.stringify({status:"completed",github_run_id:process.argv[1],eas_build_id:process.argv[2],build_url:(process.argv[3]||null),completed_at:process.argv[4],source_commit_sha:process.argv[5]}))\' "${RUN_ID}" "${BUILD_ID}" "${BUILD_URL}" "${TS}" "${SOURCE_COMMIT_SHA}")"\n          curl --fail-with-body --silent --show-error             -X PATCH "${SUPABASE_URL%/}/rest/v1/build_jobs?id=eq.${JOB_ID}"             -H "apikey: ${SUPABASE_SERVICE_ROLE_KEY}"             -H "Authorization: Bearer ${SUPABASE_SERVICE_ROLE_KEY}"             -H "Content-Type: application/json"             -H "Prefer: return=minimal"             -d "${JSON}"             || echo "::warning::Failed to update Supabase status (success)"\n\n      - name: Update Build Status - Failed\n        if: failure() && env.has_job_id == \'true\'\n        shell: bash\n        run: |\n          set -euo pipefail\n          TS="$(date -u +"%Y-%m-%dT%H:%M:%SZ")"\n          RUN_ID="${{ github.run_id }}"\n          ERR="Build failed. Check logs: https://github.com/${{ github.repository }}/actions/runs/${{ github.run_id }}"\n          SOURCE_COMMIT_SHA="$(git rev-parse HEAD)"\n          JSON="$(node -e \'console.log(JSON.stringify({status:"error",github_run_id:process.argv[1],error_message:process.argv[2],completed_at:process.argv[3],source_commit_sha:process.argv[4]}))\' "${RUN_ID}" "${ERR}" "${TS}" "${SOURCE_COMMIT_SHA}")"\n          curl --fail-with-body --silent --show-error             -X PATCH "${SUPABASE_URL%/}/rest/v1/build_jobs?id=eq.${JOB_ID}"             -H "apikey: ${SUPABASE_SERVICE_ROLE_KEY}"             -H "Authorization: Bearer ${SUPABASE_SERVICE_ROLE_KEY}"             -H "Content-Type: application/json"             -H "Prefer: return=minimal"             -d "${JSON}"             || echo "::warning::Failed to update Supabase status (failed)"\n';

export const WORKFLOW_RELEASE_BUILD_TEMPLATE = '# managed-by: k1w1\n# workflow-version: 405\n# manual-fallback-only: true\nname: Release Build (WAIT)\n\non:\n  workflow_dispatch:\n    inputs:\n      profile:\n        description: "EAS build profile"\n        required: true\n        type: choice\n        options: [production, preview, development]\n        default: production\n      ref:\n        description: "Branch/Tag/SHA to build"\n        required: true\n      strict_lockfile:\n        description: "Lockfile policy override (auto|true|false)"\n        required: false\n        type: choice\n        options: [auto, "true", "false"]\n        default: auto\n\npermissions:\n  contents: read\n\nconcurrency:\n  group: ${{ github.workflow }}-${{ inputs.ref }}-${{ inputs.profile }}\n  cancel-in-progress: false\n\njobs:\n  build:\n    name: Android Release Build\n    runs-on: ubuntu-latest\n    timeout-minutes: 60\n\n    env:\n      EXPO_TOKEN: ${{ secrets.EXPO_TOKEN }}\n      EAS_CLI_VERSION: "16.32.0"\n      SUPABASE_URL: ${{ secrets.SUPABASE_URL }}\n      SUPABASE_SERVICE_ROLE_KEY: ${{ secrets.SUPABASE_SERVICE_ROLE_KEY }}\n      K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY: ${{ secrets.K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY }}\n      WORKFLOW_VERSION: "405"\n\n    steps:\n      - name: Checkout repository\n        uses: actions/checkout@34e114876b0b11c390a56381ad16ebd13914f8d5 # v4\n        with:\n          ref: ${{ inputs.ref }}\n          fetch-depth: 0\n          persist-credentials: false\n\n      - name: Setup Node\n        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4\n        with:\n          node-version: 20\n\n      - name: Validate secrets + inputs\n        shell: bash\n        run: |\n          set -euo pipefail\n\n          case "${{ inputs.profile }}" in\n            development|preview|production) ;;\n            *) echo "::error::Invalid profile: \'${{ inputs.profile }}\'"; exit 1 ;;\n          esac\n\n          if [ -z "${EXPO_TOKEN:-}" ]; then\n            echo "::error::Missing GitHub Secret EXPO_TOKEN"\n            exit 1\n          fi\n\n          if [ "${{ inputs.profile }}" = "production" ]; then\n            if [ -z "${SUPABASE_URL:-}" ] || [ -z "${SUPABASE_SERVICE_ROLE_KEY:-}" ] || [ -z "${K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY:-}" ]; then\n              echo "::error::Production profile uses local Android credentials. Missing SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY / K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY."\n              exit 1\n            fi\n          fi\n\n      - name: Detect package manager / lockfile\n        id: lock\n        shell: bash\n        run: |\n          set -euo pipefail\n          if [ -f package-lock.json ]; then\n            {\n              echo "has_lockfile=true"\n              echo "lockfile_path=package-lock.json"\n              echo "package_manager=npm"\n            } >> "$GITHUB_OUTPUT"\n          elif [ -f npm-shrinkwrap.json ]; then\n            {\n              echo "has_lockfile=true"\n              echo "lockfile_path=npm-shrinkwrap.json"\n              echo "package_manager=npm"\n            } >> "$GITHUB_OUTPUT"\n          elif [ -f yarn.lock ]; then\n            {\n              echo "has_lockfile=true"\n              echo "lockfile_path=yarn.lock"\n              echo "package_manager=yarn"\n            } >> "$GITHUB_OUTPUT"\n          elif [ -f pnpm-lock.yaml ]; then\n            {\n              echo "has_lockfile=true"\n              echo "lockfile_path=pnpm-lock.yaml"\n              echo "package_manager=pnpm"\n            } >> "$GITHUB_OUTPUT"\n          else\n            {\n              echo "has_lockfile=false"\n              echo "lockfile_path="\n              echo "package_manager=npm"\n            } >> "$GITHUB_OUTPUT"\n          fi\n\n      - name: Setup Node (npm cache)\n        if: steps.lock.outputs.has_lockfile == \'true\' && steps.lock.outputs.package_manager == \'npm\'\n        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4\n        with:\n          node-version: 20\n          cache: npm\n          cache-dependency-path: ${{ steps.lock.outputs.lockfile_path }}\n\n      - name: Setup Node (yarn cache)\n        if: steps.lock.outputs.has_lockfile == \'true\' && steps.lock.outputs.package_manager == \'yarn\'\n        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4\n        with:\n          node-version: 20\n          cache: yarn\n          cache-dependency-path: ${{ steps.lock.outputs.lockfile_path }}\n\n      - name: Setup Node (pnpm cache)\n        if: steps.lock.outputs.has_lockfile == \'true\' && steps.lock.outputs.package_manager == \'pnpm\'\n        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4\n        with:\n          node-version: 20\n          cache: pnpm\n          cache-dependency-path: ${{ steps.lock.outputs.lockfile_path }}\n\n      - name: Setup Node (no cache - lockfile missing)\n        if: steps.lock.outputs.has_lockfile != \'true\'\n        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4\n        with:\n          node-version: 20\n\n      - name: Determine strict lockfile policy\n        id: strict_lock\n        shell: bash\n        run: |\n          set -euo pipefail\n          PROFILE="${{ inputs.profile }}"\n          OVERRIDE="${{ inputs.strict_lockfile }}"\n          case "$OVERRIDE" in\n            true)\n              echo "strict=true" >> "$GITHUB_OUTPUT"\n              ;;\n            false)\n              if [ "$PROFILE" != "development" ]; then\n                echo "::error::strict_lockfile=false is only allowed for development profile in release workflow. Preview/production remain fail-closed."\n                exit 1\n              fi\n              echo "strict=false" >> "$GITHUB_OUTPUT"\n              ;;\n            ""|auto)\n              case "$PROFILE" in\n                preview|production)\n                  echo "strict=true" >> "$GITHUB_OUTPUT"\n                  ;;\n                development)\n                  echo "strict=false" >> "$GITHUB_OUTPUT"\n                  ;;\n                *)\n                  echo "::error::Unknown profile \'$PROFILE\' while computing strict lockfile policy"\n                  exit 1\n                  ;;\n              esac\n              ;;\n            *)\n              echo "::error::Invalid strict_lockfile override \'$OVERRIDE\' (allowed: auto|true|false)"\n              exit 1\n              ;;\n          esac\n\n      - name: Install deps (package-manager-aware)\n        id: install_deps\n        shell: bash\n        env:\n          STRICT_LOCKFILE: ${{ steps.strict_lock.outputs.strict }}\n        run: |\n          set -euo pipefail\n\n          PROFILE="${{ inputs.profile }}"\n          PM="${{ steps.lock.outputs.package_manager }}"\n          if [ "${{ steps.lock.outputs.has_lockfile }}" = "true" ]; then\n            case "$PM" in\n              npm)\n                echo "mode=lockfile-${PM}" >> "$GITHUB_OUTPUT"\n                npm ci --no-audit --no-fund\n                ;;\n              yarn)\n                echo "mode=lockfile-${PM}" >> "$GITHUB_OUTPUT"\n                corepack enable || true\n                yarn install --immutable\n                ;;\n              pnpm)\n                echo "mode=lockfile-${PM}" >> "$GITHUB_OUTPUT"\n                corepack enable || true\n                pnpm install --frozen-lockfile\n                ;;\n              *)\n                echo "::error::Unknown package manager \'$PM\'"\n                exit 1\n                ;;\n            esac\n          elif [ "${STRICT_LOCKFILE}" = "true" ]; then\n            echo "::error::Strict lockfile policy enabled for profile \'${PROFILE}\', but no lockfile was found. Commit package-lock.json, npm-shrinkwrap.json, yarn.lock or pnpm-lock.yaml before running preview/production builds."\n            exit 1\n          else\n            echo "::warning::No lockfile found in repo. Development profile allows fallback to npm install (non-reproducible)."\n            echo "mode=fallback-npm-install" >> "$GITHUB_OUTPUT"\n            npm install --no-audit --no-fund\n          fi\n\n      - name: Install EAS CLI\n        shell: bash\n        run: |\n          set -euo pipefail\n          npm i -g "eas-cli@${EAS_CLI_VERSION}"\n          eas --version\n          eas whoami\n\n      - name: Export Android signing files (production only)\n        if: inputs.profile == \'production\'\n        shell: bash\n        run: |\n          set -euo pipefail\n\n          BODY="$(node - <<\'NODE\'\n          const payload = { repo: process.env.GITHUB_REPOSITORY, mode: "production" };\n          process.stdout.write(JSON.stringify(payload));\n          NODE\n          )"\n\n          RESP="$(curl -fsS -X POST "${SUPABASE_URL%/}/functions/v1/android-keystore-export" \\\n            -H "apikey: ${SUPABASE_SERVICE_ROLE_KEY}" \\\n            -H "Authorization: Bearer ${SUPABASE_SERVICE_ROLE_KEY}" \\\n            -H "Content-Type: application/json" \\\n            ${K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY:+-H "x-k1w1-admin-key: ${K1W1_EDGE_ANDROID_KEYSTORE_EXPORT_ADMIN_KEY}"} \\\n            --data "${BODY}")"\n\n          RESP_JSON="$RESP" node - <<\'NODE\'\n          const fs = require("fs");\n\n          function mask(s) {\n            if (!s) return "";\n            if (typeof s !== "string") s = String(s);\n            if (s.length <= 6) return "***";\n            return s.slice(0, 2) + "***" + s.slice(-2);\n          }\n\n          const resp = JSON.parse(process.env.RESP_JSON || "{}");\n          if (!resp.ok) {\n            console.error("❌ export failed:", resp.error || "unknown error");\n            process.exit(1);\n          }\n\n          fs.writeFileSync(\n            "android-upload-keystore.p12",\n            Buffer.from(resp.keystoreBase64, "base64"),\n            { mode: 0o600 }\n          );\n\n          const creds = {\n            android: {\n              keystore: {\n                keystorePath: "android-upload-keystore.p12",\n                keystorePassword: resp.keystorePassword,\n                keyAlias: resp.alias,\n                keyPassword: resp.keyPassword,\n              },\n            },\n          };\n\n          fs.writeFileSync("credentials.json", JSON.stringify(creds, null, 2), { mode: 0o600 });\n\n          console.log(\n            "✅ wrote signing files (alias=" +\n              (resp.alias || "unknown") +\n              ", pw=" +\n              mask(resp.keystorePassword) +\n              ")"\n          );\n          NODE\n\n      - name: Run EAS build (WAIT)\n        id: eas\n        shell: bash\n        run: |\n          set -euo pipefail\n\n          PROFILE="${{ inputs.profile }}"\n          EXT="apk"\n\n          echo " Starting EAS build (platform=android, profile=${PROFILE}) with --wait..."\n\n          {\n            echo "artifact_ext=${EXT}"\n          } >> "${GITHUB_OUTPUT}"\n\n          BUILD_OUTPUT=""\n          if ! BUILD_OUTPUT="$(eas build --platform android --profile "${PROFILE}" --non-interactive --wait 2>&1)"; then\n            CODE=$?\n            echo "${BUILD_OUTPUT}"\n            echo "::error::EAS build failed (exit ${CODE})"\n            exit "${CODE}"\n          fi\n\n          echo "${BUILD_OUTPUT}"\n\n          UUID_RE=\'[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\'\n          BUILD_ID="$(echo "${BUILD_OUTPUT}" | grep -oE "${UUID_RE}" | head -n1 || true)"\n          if [ -z "${BUILD_ID}" ]; then\n            BUILD_ID="unknown"\n          fi\n\n          BUILD_URL="$(echo "${BUILD_OUTPUT}" | grep -oE "https://expo.dev[^[:space:]]*/builds/${UUID_RE}" | head -n1 || true)"\n\n          {\n            echo "build_id=${BUILD_ID}"\n            echo "build_url=${BUILD_URL}"\n          } >> "${GITHUB_OUTPUT}"\n\n      - name: Download Android Artifact\n        if: steps.eas.outputs.build_id != \'unknown\' && steps.eas.outputs.build_id != \'\'\n        continue-on-error: true\n        shell: bash\n        run: |\n          set -euo pipefail\n          mkdir -p build\n          OUT="build/k1w1-${{ inputs.profile }}.${{ steps.eas.outputs.artifact_ext }}"\n          eas build:download --id "${{ steps.eas.outputs.build_id }}" --output "${OUT}" || {\n            echo "::warning::Failed to download artifact"\n            exit 0\n          }\n          ls -lah build || true\n\n      - name: Cleanup signing files\n        if: always()\n        shell: bash\n        run: |\n          rm -f credentials.json android-upload-keystore.p12 || true\n\n      - name: Upload Android Artifact\n        if: always()\n        continue-on-error: true\n        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02 # v4\n        with:\n          name: k1w1-android-${{ inputs.profile }}-${{ github.run_number }}\n          path: build/*\n          retention-days: 30\n          if-no-files-found: warn\n\n      - name: Summary\n        if: always()\n        shell: bash\n        run: |\n          {\n            echo "## Release Build Summary"\n            echo ""\n            echo "- workflow version: \\`${WORKFLOW_VERSION}\\`"\n            echo "- Profile: ${{ inputs.profile }}"\n            echo "- Ref: ${{ inputs.ref }}"\n            echo "- Package manager: ${{ steps.lock.outputs.package_manager }}"\n            echo "- Lockfile: ${{ steps.lock.outputs.lockfile_path || \'none\' }}"\n            echo "- Strict lockfile policy: ${{ steps.strict_lock.outputs.strict }}"\n            echo "- Dependency install mode: ${{ steps.install_deps.outputs.mode }}"\n            echo "- Build URL: ${{ steps.eas.outputs.build_url }}"\n            echo "- Build ID: ${{ steps.eas.outputs.build_id }}"\n            echo ""\n            echo "> Hinweis: Dieser Workflow ist ein manueller Direktpfad und umgeht die App-seitige Single Source of Truth."\n          } >> "$GITHUB_STEP_SUMMARY"\n';
